Given an array arr[] containing n positive integers,  find the length of the longest bitonic subsequence. A subsequence of numbers is called bitonic if it is first strictly increasing, then strictly decreasing.Note: Only strictly increasing (no decreasing part) or a strictly decreasing sequence should not be considered as a bitonic sequence.Examples:Input: arr[] = [1, 2, 5, 3, 2]Output: 5Explanation: The sequence [1, 2, 5] is increasing and the sequence [3, 2] is decreasing so merging both we will get length 5.Input: arr[] = [1, 11, 2, 10, 4, 5, 2, 1]Output: 6Explanation: The bitonic sequence [1, 2, 10, 4, 2, 1] has length 6.Try It YourselfTable of Content[Naive Approach] Generate All Subsequences - O(2^n x n) Time and O(n) Space[Better Approach] Dynamic Programming - O(n ^ 2) Time and O(n) Space[Expected Approach] LIS/LDS Using Binary Search - O(n log n) Time and O(n) Space[Naive Approach] Generate All Subsequences - O(2^n x n) Time and O(n) SpaceThe idea is that Generate every possible subsequence and check whether it is bitonic. For every subsequence:Find the point where the sequence changes from increasing to decreasing.Ensure the increasing part is strictly increasing.Ensure the decreasing part is strictly decreasing.Ensure both parts are non-empty.This approach is mainly useful for understanding the problem and for very small arrays.
            C++

    #include <iostream>
#include <vector>
using namespace std;

bool isBitonic(const vector<int>& seq) {
    int n = seq.size();

    if (n < 3)
        return false;

    int i = 1;

    // Strictly increasing part.
    while (i < n && seq[i] > seq[i - 1]) {
        i++;
    }

    // There must be a decreasing part.
    if (i == 1 || i == n)
        return false;

    // Strictly decreasing part.
    while (i < n && seq[i] < seq[i - 1]) {
        i++;
    }

    return i == n;
}

int longestBitonicSequence(vector<int>& arr) {
    int n = arr.size();
    int maxLen = 0;

    for (int mask = 0; mask < (1 << n); mask++) {
        vector<int> seq;

        for (int i = 0; i < n; i++) {
            if (mask & (1 << i)) {
                seq.push_back(arr[i]);
            }
        }

        if (isBitonic(seq)) {
            maxLen = max(maxLen, (int)seq.size());
        }
    }

    return maxLen;
}

int main() {
    vector<int> arr1 = {1, 2, 5, 3, 2};
    cout << longestBitonicSequence(arr1) << endl;

    vector<int> arr2 = {1, 11, 2, 10, 4, 5, 2, 1};
    cout << longestBitonicSequence(arr2) << endl;

    return 0;
}


